-- The weekly recap (#63): who cooked, the week's hit, and a forgotten favorite, for the week of October 25, 2026.
begin;
select plan(14);

create function pg_temp.as_user(uid uuid) returns void language sql as $$
  select set_config('request.jwt.claims', json_build_object('sub', uid, 'role', 'authenticated')::text, true),
         set_config('role', 'authenticated', true);
$$;

create function pg_temp.recap(from_date date = '2026-10-25', to_date date = '2026-10-31') returns jsonb language sql as $$
  select public.week_recap('00000000-0000-0000-0000-0000000000a0', from_date, to_date)::jsonb;
$$;

