-- Bob, a member, sees the household's recap.
select pg_temp.as_user('b0000000-0000-0000-0000-00000000000b');
select is((pg_temp.recap() ->> 'logged')::int, 6, 'logged: the week''s six logged nights, quick picks included');
select is(pg_temp.recap() -> 'cooks',
  '["00000000-0000-0000-0000-0000000000a3", "00000000-0000-0000-0000-0000000000a2", "00000000-0000-0000-0000-0000000000a1"]'::jsonb,
  'cooks: in the order they first cooked, not takeout, and not someone removed');
select is(pg_temp.recap() -> 'top_dish',
  '{"meal_id": "00000000-0000-0000-0000-0000000001c0", "name": "Chili"}'::jsonb,
  'the week''s hit: a tie on likes goes to the latest night; removed and eats-separately votes don''t count');
select is(pg_temp.recap() -> 'forgotten_favorite',
  '{"meal_id": "00000000-0000-0000-0000-0000000001c4", "name": "Pie"}'::jsonb,
  'a forgotten favorite: most fans, in rotation, six weeks or more; not lasagna, ribs, gumbo, or Tot''s stew');
select is(pg_temp.recap('2026-10-28', '2026-10-28') -> 'top_dish', 'null'::jsonb, 'no like that night, no hit');
select is((pg_temp.recap('2026-10-18', '2026-10-24') ->> 'logged')::int, 0, 'a draft week logged nothing');
select is(pg_temp.recap('2026-10-18', '2026-10-24') -> 'cooks', '[]'::jsonb, 'and thanks nobody');

-- Dan changes his mind about pie: one fan each, so the longest since wins.
reset role;
update public.reactions set reaction = 'good'
where meal_log_id = '00000000-0000-0000-0000-000000000405' and member_id = '00000000-0000-0000-0000-0000000000a3';
select pg_temp.as_user('b0000000-0000-0000-0000-00000000000b');
select is(pg_temp.recap() -> 'forgotten_favorite' ->> 'name', 'Pot roast', 'a tie on fans goes to the longest since');

-- The owner sees the same.
select pg_temp.as_user('a0000000-0000-0000-0000-00000000000a');
select is(pg_temp.recap() -> 'top_dish' ->> 'name', 'Chili', 'the owner sees the same recap');

-- Another household learns nothing.
select pg_temp.as_user('c0000000-0000-0000-0000-00000000000c');
select is(pg_temp.recap(),
  '{"logged": 0, "cooks": [], "top_dish": null, "forgotten_favorite": null}'::jsonb,
  'another household''s member gets nothing');

reset role;
select ok(not has_function_privilege('anon', 'public.week_recap(uuid, date, date)', 'execute'), 'not for anon');
select ok(not has_function_privilege('public', 'public.week_recap(uuid, date, date)', 'execute'), 'not for public');
select ok(has_function_privilege('authenticated', 'public.week_recap(uuid, date, date)', 'execute'),
  'for signed-in people');
select is((select provolatile from pg_proc where proname = 'week_recap'), 's', 'read-only');

select * from finish();
rollback;
